validator:
function validate(input) {
  const [{ Rides = [] }] = input;
  const ids = new Set();
  for (const [id, driver, passenger] of Rides) {
    if (id === null || driver === null || passenger === null) return 'Rides rows may not contain null.';
    if (ids.has(id)) return `ride_id ${id} appears twice in Rides.`;
    if (driver === passenger) return `In ride ${id} the driver is also the passenger.`;
    ids.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const people = small ? 5 : 300, count = small ? Math.floor(rand() * 9) : 2000;
  const Rides = [];
  for (let i = 0; i < count; i++) {
    const driver = 1 + Math.floor(rand() * people);
    let passenger = 1 + Math.floor(rand() * (people - 1));
    if (passenger >= driver) passenger++;
    Rides.push([i + 1, driver, passenger]);
  }
  return [{ Rides }];
}
